    await F2.wait_for_timeout(250); ok("the other teacher moves to the jumps with them",await F2.locator('.field-table').count()==1)
    await F.click('[data-act=faddopen]'); await F.click('.addlist .pick:not(.on) >> nth=0'); await F.wait_for_timeout(100); await F.click('.modal [data-act=closemodal]'); await F.wait_for_timeout(100)
    ok("Add an athlete stays for late arrivals",await F.evaluate("fieldView(fieldGroupOpen()).rows.length")==4)
    # A1.9 high jump, iPad (decisions 40, 41)
    await F.evaluate("(()=>{const f=A.R.fgroups.find(f=>f.key==='HJ|F|18');A.f.station=f.station;fOpen(f.id)})()"); await F.wait_for_timeout(100)
    for i in range(3): await F.click('.namebtn:not(.sel) >> nth=0'); await F.wait_for_timeout(40)
    await F.click('[data-act=fstart]'); await F.wait_for_timeout(120)
