    names=await F.evaluate(f"{V}.rows.map(r=>r.p.f+' '+r.p.s)")
    up1=await F.get_attribute('.hjc.upc','aria-label')
    ok("the box that is up is highlighted: the first athlete at 1.10, no Now up bar",names[0] in up1 and "1.10 metres" in up1 and await F.locator('.checkline').count()==0 and await F.locator('.chip:has-text("Next")').count()==1)
    await hj(F,'O')
